registro Retangulo {
    largura: inteiro,
    altura: inteiro,
}

funcao area(r: Retangulo) -> inteiro {
    retorne 0;
}

funcao inicio() {
    seja mutavel largura: inteiro = 0;
    seja mutavel altura: inteiro = 0;
    leia(largura);
    leia(altura);
    seja r: Retangulo = Retangulo { largura: largura, altura: altura };
    escreva(area(r));
}
